'use strict';

function createClient(supabaseUrl, supabaseKey, options) {
  const headers = { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}` };

  async function request(path, opts = {}) {
    const url = supabaseUrl + path;
    const res = await fetch(url, {
      ...opts,
      headers: { ...headers, ...(opts.headers || {}) },
    });
    return res;
  }

  const auth = {
    getUser: async () => ({ data: { user: null }, error: null }),
    getSession: async () => ({ data: { session: null }, error: null }),
    signInWithPassword: async () => ({ data: null, error: null }),
    signOut: async () => ({ error: null }),
    onAuthStateChange: () => ({ data: { subscription: { unsubscribe: () => {} } } }),
    exchangeCodeForSession: async () => ({ data: null, error: null }),
    setSession: async () => ({ data: null, error: null }),
    refreshSession: async () => ({ data: null, error: null }),
    signInWithOAuth: async () => ({ data: null, error: null }),
    signUp: async () => ({ data: null, error: null }),
    resetPasswordForEmail: async () => ({ data: null, error: null }),
    updateUser: async () => ({ data: null, error: null }),
  };

  function from(table) {
    const state = { _table: table, _filters: [], _select: '*', _order: null, _limit: null, _single: false };
    const chain = {
      select: (cols) => { state._select = cols || '*'; return chain; },
      insert: (data) => chain,
      update: (data) => chain,
      delete: () => chain,
      upsert: (data) => chain,
      eq: (col, val) => chain,
      neq: (col, val) => chain,
      gt: (col, val) => chain,
      gte: (col, val) => chain,
      lt: (col, val) => chain,
      lte: (col, val) => chain,
      like: (col, val) => chain,
      ilike: (col, val) => chain,
      in: (col, vals) => chain,
      is: (col, val) => chain,
      order: (col, opts) => chain,
      limit: (n) => chain,
      range: (from, to) => chain,
      single: () => { state._single = true; return chain; },
      maybeSingle: () => { state._single = true; return chain; },
      then: (resolve) => resolve({ data: null, error: null }),
    };
    return chain;
  }

  function storage() {
    return {
      from: (bucket) => ({
        upload: async () => ({ data: null, error: null }),
        download: async () => ({ data: null, error: null }),
        getPublicUrl: () => ({ data: { publicUrl: '' } }),
        remove: async () => ({ data: null, error: null }),
        list: async () => ({ data: [], error: null }),
      }),
    };
  }

  function rpc(fn, args, opts) {
    return Promise.resolve({ data: null, error: null });
  }

  return { auth, from, storage: storage(), rpc };
}

module.exports = { createClient };
module.exports.createClient = createClient;
